const defibReferences={Biphasic:{external:[2,4],internal:[.2,.4],suffix:'B'},Monophasic:{external:[4,6],internal:[.5,1],suffix:'M'}};
function defibEnergy(weight,joulesPerKg){return positive(weight)&&positive(joulesPerKg)?Number(weight)*Number(joulesPerKg):NaN}
function emergencyExtras(cat){
 if(!data.defibWave)data.defibWave='Biphasic';
 const r=defibReferences[data.defibWave];
 return `${cat?'<article class="card category"><h3>Lidocaine · feline restriction</h3><p>RECOVER advises against IV lidocaine for feline refractory VF / pulseless VT. The canine calculator appears when Dog is selected; amiodarone remains available for cats.</p></article>':''}<article class="card category"><span class="tag">ESMOLOL · AFTER LOADING DOSE</span><h3>CPR infusion</h3><div class="formrow">${field('esmoCriDose','Infusion rate',50,'µg/kg/min')}${field('esmoCriConc','Actual pump concentration',10,'mg/mL')}</div><p class="ref">Use the actual prepared concentration, including any dilution.</p>${result('esmoCriResult')}</article><div class="sectionhead category"><div><p class="eyebrow">ELECTRICAL DEFIBRILLATION</p><h2>External & internal energy</h2><p>For pulseless VF / VT · not asystole or PEA. Confirm rhythm and equipment.</p></div></div><label>Defibrillator waveform<select id="defibWave">${Object.keys(defibReferences).map(w=>`<option ${w===data.defibWave?'selected':''}>${w}</option>`).join('')}</select></label><div class="grid category"><article class="card"><span class="tag">EXTERNAL · ${data.defibWave.toUpperCase()}</span><h3>Closed-chest defibrillation</h3>${result('externalRange')}${field('defibExt'+r.suffix,'Selected INITIAL energy',r.external[0],'J/kg')}${result('externalSelected')}<p class="ref">If unsuccessful, double the initial external dose for shock #2 and retain that dose for later shocks. Do not keep doubling.</p></article><article class="card"><span class="tag">INTERNAL · ${data.defibWave.toUpperCase()}</span><h3>Open-chest defibrillation</h3>${result('internalRange')}${field('defibInt'+r.suffix,'Selected internal energy',r.internal[0],'J/kg')}${result('internalSelected')}<p class="ref">For trained teams using internal paddles. Internal energy is lower; use the internal protocol and device instructions. External escalation is not applied here.</p></article><article class="card"><h3>Verify device settings</h3><p>Calculated joules are not rounded to a device setting. Confirm supported energy steps, maximum output, paddles / pads, waveform, and team safety before discharge.</p><p>Biphasic equipment is preferred. These are energy calculations, not device controls.</p></article></div>`;
}
function calculateEmergency(){
 if(page!==1)return;
 const put=(id,html)=>{const e=$('#'+id);if(e)e.innerHTML=html},w=kg(),r=defibReferences[data.defibWave||'Biphasic'];
 const dose=positive(data.esmoCriDose)?Number(data.esmoCriDose):NaN,conc=positive(data.esmoCriConc)?Number(data.esmoCriConc):NaN,total=w*dose*60/1000;
 put('esmoCriResult',`${fmt(total/conc)} mL/hr<small>${fmt(total)} mg/hr · weight × µg/kg/min × 60 ÷ 1000 ÷ mg/mL</small>`);
 for(const [kind,id]of [['external','externalRange'],['internal','internalRange']])put(id,`${fmt(defibEnergy(w,r[kind][0]))}–${fmt(defibEnergy(w,r[kind][1]))} J<small>RECOVER chart: ${r[kind][0]}–${r[kind][1]} J/kg × patient weight</small>`);
 const ext=data['defibExt'+r.suffix],int=data['defibInt'+r.suffix];
 const warning=(v,limits)=>positive(v)&&(Number(v)<limits[0]||Number(v)>limits[1])?'<small>Selected initial factor is outside the reference range; verify the clinical protocol.</small>':'';
 put('externalSelected',`${fmt(defibEnergy(w,ext))} J initial<small>Shock #2 and later if initial shock fails: ${fmt(defibEnergy(w,positive(ext)?Number(ext)*2:NaN))} J</small>${warning(ext,r.external)}`);
 put('internalSelected',`${fmt(defibEnergy(w,int))} J<small>${positive(int)?fmt(Number(int)):'—'} J/kg × ${fmt(w)} kg</small>${warning(int,r.internal)}`);
}
document.addEventListener('change',e=>{if(e.target.id==='defibWave'){data.defibWave=e.target.value;render()}});
